import {PORTMANN_STORE,startDairy,dairyStep,careCheese,collectCheese,sellAlpProduct,ripeBatch} from './dairy.mjs';
import {exchangeInventory,money} from './progression.mjs';
export function createDairyPanels({getState,capture,show,changed}){
 let feedbackTone='neutral';const $=id=>document.getElementById(id);function run(fn,reopen){capture();const r=fn();feedbackTone=r.ok?'success':'danger';if(r.ok)changed();reopen(r.message);}
 const msg=m=>m?'<p class="panel-message" data-game-tone="'+feedbackTone+'" role="status">'+(feedbackTone==='danger'?'✕ ':feedbackTone==='success'?'✓ ':'')+m+'</p>':'';
 function workshop(m=''){capture();const s=getState(),a=s.dairy.active;
 const labels={warm:'Milch wärmen & Lab beigeben',set:'Milch gerinnen lassen',cut:'Bruch schneiden',stir:'Käsebruch rühren',press:'In die Form pressen',salt:'Salzen & in die Höhle lagern'};
 const steps=['warm','set','cut','stir','press','salt'];const diagram=a?'<div class="cheese-worktop"><svg viewBox="0 0 420 200" role="img" aria-label="Käse-Chessi: '+labels[a.stage]+'"><defs><linearGradient id="copper" x2="1" y2="1"><stop stop-color="#d8a16e"/><stop offset=".5" stop-color="#99613c"/><stop offset="1" stop-color="#e7b487"/></linearGradient></defs><path d="M85 60 Q75 172 210 180 Q345 172 335 60" fill="url(#copper)" stroke="#754d36" stroke-width="5"/><ellipse cx="210" cy="60" rx="125" ry="39" fill="'+(['press','salt'].includes(a.stage)?'#ddb764':'#f4e6b7')+'" stroke="#9c714b" stroke-width="7"/>'+Array.from({length:a.cuts},(_,i)=>'<path d="M'+(145+i*40)+' 32 L'+(125+i*40)+' 85" stroke="#ad9b65" stroke-width="3"/>').join('')+(a.stage==='stir'?'<path d="M190 55 Q260 20 285 68 Q230 102 165 75" fill="none" stroke="#a8864a" stroke-width="4"/><path d="M220 60 L285 5" stroke="#765538" stroke-width="9"/>':'')+'<text x="210" y="140" text-anchor="middle" fill="#fff5da" font-size="22">'+(a.stage==='warm'?a.temperature+' °C':a.stage==='cut'?a.cuts+' / 4 Schnitte':a.stage==='stir'?a.stirs+' / 6 Rührzüge':'Portmann Alp')+'</text></svg></div>':'';
 const controls=!a?'<button id="dairy-start" class="primary">Käserunde beginnen · 4 Milch, 1 Lab, 1 Salz, 1 Holz</button>':a.stage==='warm'?'<div class="temperature"><span style="left:'+((a.temperature-20)*5)+'%"></span></div><p>Grüner Bereich: 30–34 °C. Du bestimmst das Tempo.</p><p data-game-tone="'+(a.temperature>34?'danger':a.temperature<30?'warning':'success')+'">'+(a.temperature>34?'ZU HEISS – zuerst abkühlen.':a.temperature<30?'Noch zu kalt – vorsichtig wärmen.':'✓ Richtige Temperatur – jetzt Lab einrühren.')+'</p><div class="actions"><button data-dairystep="heat">Wärmen +2 °C</button><button data-dairystep="cool">Abkühlen −2 °C</button><button data-dairystep="lab" class="primary" '+(a.temperature<30||a.temperature>34?'disabled':'')+'>Lab einrühren</button></div>':'<button class="primary" data-dairystep="'+({set:'wait',cut:'cut',stir:'stir',press:'press',salt:'store'}[a.stage])+'">'+({set:'Dickete prüfen · geronnen',cut:'Mit der Käseharfe schneiden',stir:'Einen Rührzug machen',press:'In die Form pressen',salt:'Salzen und ins Reiferegal legen'}[a.stage])+'</button>';
 show('<span class="eyebrow">DEINE ALP · CHÄS-CHESSI</span><h2>'+(a?labels[a.stage]:'Aus deiner Milch wird Alpkäse')+'</h2>'+msg(m)+'<p>Heu und Eimer aus der Scheune holen → Kühe füttern, tränken und pflegen → Berta und Lotti melken → hier käsen → im Höhlenkeller reifen und pflegen → im Portmann-Store der Stadt verkaufen.</p><ol class="dairy-steps">'+steps.map(k=>'<li class="'+(a?.stage===k?'active':'')+'">'+labels[k]+'</li>').join('')+'</ol>'+diagram+controls+'<p>Vorrat: '+(s.inventory.milk||0)+' Milch · '+(s.inventory.rennet||0)+' Lab · '+(s.inventory.salt||0)+' Salz · '+(s.inventory.wood||0)+' Holz. Lab und Salz gibt es am Dorfladen. Ein Laib braucht vier Portionen Milch; beide Kühe geben zusammen vier pro versorgtem Tag.</p><small>Vereinfachtes Crafting-Spiel ohne Zeitdruck. Jeder Schritt wird gespeichert. Im Keller reift ein Laib über mindestens drei Spielnächte; Offline-Zeit und echte Tage zählen nicht.</small>');if(!a)$('dairy-start').onclick=()=>run(()=>startDairy(s,exchangeInventory),workshop);for(const b of document.querySelectorAll('[data-dairystep]'))b.onclick=()=>run(()=>dairyStep(s,b.dataset.dairystep),workshop);
 }
 function cellar(m=''){capture();const s=getState();show('<span class="eyebrow">UNTER DER PORTMANN-ALP</span><h2>Dein Höhlenkäsekeller</h2>'+msg(m)+'<p>Kühle Felswände, Holzregale und Zeit: Jeder Laib braucht mindestens drei Nächte und Pflege an drei unterschiedlichen Spieltagen. Einmal am Tag mit 1 Wasser und 1 Salz schmieren und wenden. Über Nacht verschlechtert sich nichts unwiderruflich; vergessene Pflege kannst du nachholen.</p><p>Reifeplätze: '+s.dairy.batches.length+' / 12 · '+s.dairy.sold+' Laibe im Stadtladen verkauft</p><div class="item-grid">'+s.dairy.batches.map(b=>'<article class="item-card"><h3>Portmann-Laib '+b.id+'</h3><p>'+Math.min(3,s.day-b.madeDay)+' / 3 Nächte · '+b.careDays.length+' / 3 Pflegetage</p><p>'+(ripeBatch(s,b)?'Verkaufsreif':b.careDays.includes(s.day)?'Heute frisch geschmiert':'Pflege wartet auf dich')+'</p><button data-cheesecare="'+b.id+'" '+(ripeBatch(s,b)||b.careDays.length>=3||b.careDays.includes(s.day)?'disabled':'')+'>Schmieren & wenden</button><button data-cheesetake="'+b.id+'" '+(!ripeBatch(s,b)?'disabled':'')+'>Reifen Laib einpacken</button></article>').join('')+'</div>'+(!s.dairy.batches.length?'<p>Dein erster Laib entsteht am Chessi eine Ebene höher.</p>':''));for(const b of document.querySelectorAll('[data-cheesecare]'))b.onclick=()=>run(()=>careCheese(s,Number(b.dataset.cheesecare),exchangeInventory),cellar);for(const b of document.querySelectorAll('[data-cheesetake]'))b.onclick=()=>run(()=>collectCheese(s,Number(b.dataset.cheesetake),exchangeInventory),cellar);}
 function store(m=''){capture();const s=getState();show('<span class="eyebrow">PORTMANN · STADT</span><h2>Vom Alphof in den Laden</h2>'+msg(m)+'<p>Hier verkaufst du die Erzeugnisse deiner Alp. Das Geld bleibt im selben Spielstand und finanziert deine Crafting-Ausbaupläne.</p><div class="item-grid">'+[['caveCheese','Höhlengereifter Portmann-Alpkäse',2500],['chocolate','Portmann-Alpschokolade',650]].map(([id,name,price])=>'<article class="item-card"><h3>'+name+'</h3><p>'+money(price)+' pro Stück · '+(s.inventory[id]||0)+' im Rucksack</p><button data-alpsell="'+id+'" '+(!(s.inventory[id]>0)?'disabled':'')+'>Ein Stück verkaufen</button></article>').join('')+'</div>');for(const b of document.querySelectorAll('[data-alpsell]'))b.onclick=()=>run(()=>sellAlpProduct(s,b.dataset.alpsell,exchangeInventory),store);}
 return{workshop,cellar,store};
}
